#nullable enable // autogenerated

using MVZ2Logic.UI;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.UI.Mainmenu
{
    public class AchievementEntryUI : MonoBehaviour
    {
        public void UpdateEntry(AchievementEntryViewData viewData)
        {
            iconImage.SetSprite(viewData.icon);
            notEarnedIconImage.SetSprite(viewData.icon);
            iconImage.SetEnabled(viewData.earned);
            notEarnedIconImage.SetEnabled(!viewData.earned);
            nameText.text = viewData.name;
            earnedObj.SetActive(false); // 先禁用，这样会触发Translator的OnEnable，重新对文本进行翻译，防止切换语言后出现问题。
            earnedObj.SetActive(viewData.earned);
            descriptionText.text = viewData.description;
        }
        [SerializeField]
        private ImageResolver iconImage = null!;
        [SerializeField]
        private ImageResolver notEarnedIconImage = null!;
        [SerializeField]
        private TextMeshProUGUI nameText = null!;
        [SerializeField]
        private GameObject earnedObj = null!;
        [SerializeField]
        private TextMeshProUGUI descriptionText = null!;
    }
    public struct AchievementEntryViewData
    {
        public Sprite? icon;
        public string name;
        public bool earned;
        public string description;
    }
}
